{
  "complexity": "deep",
  "requiredCapabilities": [
    "商業策略判斷",
    "財務與單位經濟分析",
    "風險評估與不可逆性管理",
    "資源配置與執行路徑設計"
  ],
  "assignments": [
    {
      "agentId": "business_strategist",
      "mission": "基於題目資訊，完成A/B/C三案的單位經濟、能力建設需求、品牌/資料控制、講師負荷與資源占用、現金流與風險對比，明確選定一個主策略並給出最重要理由；提出最大反方論點；列出可改變決策的條件（以條件式）；設計未來6–12個月可回收試點與里程碑，降低不可逆風險並檢驗：平台轉企客轉化、社群營運成本、講師瓶頸。",
      "priority": "high"
    }
  ],
  "requiresRedTeam": false,
  "reason": "決策屬公司級兩年配置，屬深度策略。題目限制僅用既有資訊，不需外部市場蒐集；品牌控制與定位影響可由商業策略視角權衡。單一商業策略專家可完成取捨、反方論點、門檻條件與風險降低方案，最小充分。"
}

{
  "complexity": "deep",
  "requiredCapabilities": [
    "commercial strategy and risk assessment",
    "creative operations and brand governance feasibility"
  ],
  "assignments": [
    {
      "agentId": "business_strategist",
      "mission": "Build A/B/C decision with quantified risk/benefit under given constraints. Test delivery viability vs single half-time senior, fixed 14-week deadline, 80-site go-live. Recommend path, list reversal conditions, and non-negotiable commercial/governance terms (scope boundaries, phased acceptance, change controls, decision SLAs, client single-threaded owner, penalties/bonuses). Ensure plan leverages external suppliers without ceding final brand control.",
      "priority": "high"
    },
    {
      "agentId": "brand_creative",
      "mission": "Stress-test creative/brand workflow: can core brand system, approvals, cross-site consistency, executive reviews be owned with only one senior at 50% for weeks 1–10 and freelancers for production? Define minimal viable brand system for week 14, gating, approval cadence, QA, escalation, and what must slip to phase 2. Identify delivery risks, flip conditions, and non-negotiables to protect quality.",
      "priority": "high"
    }
  ],
  "requiresRedTeam": false,
  "reason": "This is a high-stakes go/no-go and contract-terms decision hinging on commercial risk and delivery capacity. Business Strategist determines the recommendation and deal guardrails; Brand/Creative validates whether execution is feasible and defines gating/quality controls. No market research is needed because the brief limits judgment to provided facts."
}

{
  "complexity": "deep",
  "requiredCapabilities": [
    "strategy and financial-risk assessment",
    "experimental evidence interpretation",
    "decision framing under uncertainty"
  ],
  "assignments": [
    {
      "agentId": "business_strategist",
      "mission": "Using only the provided test facts, recommend A/B/C for the second site. Interpret evidence quality (repeat buys, net-new acquisition, pricing power, HQ-senior dependence, event attendance bias), identify the most misread metric and why, state what 6‑month results would change the call (clear thresholds), and judge if evidence suffices for a 3+ year irreversible investment. Deliver a concise, board-ready rationale with conditionality.",
      "priority": "high"
    }
  ],
  "requiresRedTeam": false,
  "reason": "This is a major investment decision based solely on given pilot evidence. It needs one strategist to interpret experimental signals, weigh risks, set decision thresholds, and recommend among A/B/C without external market data. Additional roles would not change the decision."
}

{
  "complexity": "deep",
  "requiredCapabilities": [
    "business strategy and risk assessment",
    "brand architecture and execution planning"
  ],
  "assignments": [
    {
      "agentId": "business_strategist",
      "mission": "Assess options A/B/C against contract/renewal timing, operational readiness (systems can integrate now), regulatory disclosure, and commercial risks. Recommend one path with rationale across business risk and client relationship impact; define decision gates over 12 months; and list specific risks to monitor (renewal churn, endorsement acceptance, re-confirmation workload) strictly using provided facts.",
      "priority": "high"
    },
    {
      "agentId": "brand_creative",
      "mission": "Design the brand architecture and 12‑month transition approach aligned to the chosen option: preserve acquired-brand equity, define endorsement system, messaging to reassure clients, and touchpoint sequencing (signage, materials, digital, CRM) synced with integration and normal update cycles. Outline execution order and internal KPIs to track confusion and acceptance within given constraints.",
      "priority": "high"
    }
  ],
  "requiresRedTeam": false,
  "reason": "Decision affects brand architecture and commercial risk; it needs only business and brand strategy. No external research is required per prompt, so two specialists suffice for a high-quality, actionable recommendation."
}
